inline std::string build_read_command(const std::filesystem::path& path,
                                      read_config cfg,
                                      const std::vector<std::string>& extra_decode_as = {}) {
	command_builder cmd(cfg.program);

	cmd.read_file(path);
	if(cfg.no_name_resolution) {
		cmd.no_name_resolution();
	}
	if(cfg.quiet) {
		cmd.quiet();
	}
	cmd.fields_output()
	   .header(cfg.header)
	   .tab_separator();

	for(const auto &arg : cfg.extra_args) {
		cmd.arg(arg);
	}
	// Structured preferences follow extra_args so the explicit reassembly policy wins.
	for(const auto &arg : reassembly_args(cfg.reassembly)) cmd.arg(arg);
	for(const auto& decode : cfg.decode_as) {
		cmd.decode_as(decode);
	}
	for(const auto& decode : extra_decode_as) {
		cmd.decode_as(decode);
	}
	for(const auto& proto : cfg.disable_protocols) {
		cmd.disable_protocol(proto);
	}

	auto fields = cfg.fields.empty() ? default_fields() : cfg.fields;
	fields.insert(fields.end(), cfg.extra_fields.begin(), cfg.extra_fields.end());
