void continuous_tshark_source::read_output(tsv_sink &sink) {
	FILE *stream = fdopen(m_stdout_fd, "r");
	if(!stream) {
		m_reader_ok = false;
		return;
	}
	m_stdout_fd = -1;
	std::array<char, 32768> line{};
	const auto read_line = [&] {
		sink.on_tsv_read_begin();
		auto *result = fgets(line.data(), static_cast<int>(line.size()), stream);
		sink.on_tsv_read_end();
		return result;
	};
	if(read_line() != nullptr) {
		m_reader_ok = sink.on_tsv_header(line.data());
	}
	else {
		m_reader_ok = false;
	}
	while(m_reader_ok && read_line() != nullptr) {
		m_reader_ok = sink.on_tsv_row(line.data());
	}
	if(ferror(stream)) m_reader_ok = false;
	sink.on_tsv_end();
	fclose(stream);
}

bool continuous_tshark_source::finish() {
	if(m_stdin_fd >= 0) { close(m_stdin_fd); m_stdin_fd = -1; }
	int status{};
	pid_t waited;
	waited = m_resources.wait(m_pid, &status, 0);
	const bool ok = waited > 0 && WIFEXITED(status) && WEXITSTATUS(status) == 0;
	if(!ok) trace(0, "error: continuous tshark failed at EOF: wait=%d status=%d", static_cast<int>(waited), status);
	if(waited > 0) m_pid = -1;
	if(m_reader.joinable()) m_reader.join();
	m_diagnostics.finish();
	return ok;
}

